triage_tool:
{
  "description": "Submit the route for the planner's message.",
  "input_schema": {
    "additionalProperties": false,
    "properties": {
      "question": {
        "anyOf": [
          {
            "maxLength": 300,
            "type": "string"
          },
          {
            "type": "null"
          }
        ],
        "default": null,
        "title": "Question"
      },
      "reason": {
        "default": "",
        "maxLength": 200,
        "title": "Reason",
        "type": "string"
      },
      "route": {
        "enum": [
          "read",
          "plan",
          "clarify",
          "decline_commit"
        ],
        "title": "Route",
        "type": "string"
      }
    },
    "required": [
      "route"
    ],
    "title": "Triage",
    "type": "object"
  },
  "name": "submit_triage"
}
